#!/usr/bin/env node
// Records the painted slice goldens (`painted` in test/goldens/slices.json): the plates of PAINTED_PLATES
// (test/conformance/plates.ts) sliced by an engine that serves protocol 2.2 ('paint.v1'), on both variants,
// through the host's own request checks (host/src/ops.ts) and the bridge (host/src/bridge.ts). Both variants
// must give the same G-code (the "; generated by" line aside); the conformance suite then requires it of
// every host. The unpainted goldens (record-slices-v1.mjs) stay as the v0.1.0 release recorded them.
//
//   node tools/goldens/record-slices-painted.mjs [engine folder]     # default dist/ (npm run build:engine)
//
// A native OrcaSlicer CLI built from the pinned commit could record the same plates from a 3MF holding the
// meshes and codes (engine/README.md, "Parity with a native CLI"); none is built yet, so the engine records
// them, and the reference says which build did.
import { createHash } from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { loadEngine, runSlice } from '../../host/src/bridge.ts';
import { sliceJob } from '../../host/src/ops.ts';
import { PAINTED_PLATES, comparable } from '../../test/conformance/plates.ts';

const repo = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const engineDir = path.resolve(process.argv[2] ?? path.join(repo, 'dist'));
const manifest = JSON.parse(fs.readFileSync(path.join(engineDir, 'manifest.json'), 'utf8'));
const version = manifest.version ?? JSON.parse(fs.readFileSync(path.join(repo, 'package.json'), 'utf8')).version;

const plates = {};
for (const variant of ['st', 'mt']) {
  const { engine } = await loadEngine(pathToFileURL(engineDir + path.sep).href, variant);
  for (const plate of PAINTED_PLATES) {
    const output = runSlice(engine, { ...sliceJob(plate.params()), toolpaths: false });
    (plates[plate.id] ??= {})[variant] = {
      sha256: createHash('sha256').update(comparable(output.gcode)).digest('hex'),
      bytes: output.gcode.length,
      layers: output.stats.layers,
      printTimeText: output.stats.printTimeText,
      filamentMm: output.stats.filamentMm,
    };
  }
  console.log(`${variant}: ${PAINTED_PLATES.length} plates`);
}
for (const [id, { st, mt }] of Object.entries(plates)) {
  if (st.sha256 !== mt.sha256) throw new Error(`${id}: st and mt give different G-code (${st.sha256} and ${mt.sha256})`);
}

const out = path.join(repo, 'test/goldens/slices.json');
const goldens = JSON.parse(fs.readFileSync(out, 'utf8'));
goldens.painted = {
  reference: {
    version,
    // The goldens hold only for an engine built from this Orca commit.
    orcaCommit: manifest.orcaCommit,
    recordedWith: `the engine ${version} (st and mt alike); no native OrcaSlicer CLI is built from the pinned commit yet`,
  },
  plates,
};
fs.writeFileSync(out, JSON.stringify(goldens, null, 1) + '\n');
console.log(`OK: ${out}`);
